// Deterministic synthetic markdown: nothing third-party, regenerated byte for byte from a seed. It mixes every GFM
// construct, nesting, tabs, entities, raw HTML, definitions, footnotes, CRLF / CR files and chat-style answers, so
// the identity harnesses keep a corpus that exists in a fresh checkout without any download.
import {chatAnswer} from './perf/chat-text.mjs'

function rng(seed) { let s = seed >>> 0; return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296 } }
const WORDS = 'alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega parser token stream node tree block span line'.split(' ')

export function syntheticDocs(count = 240, seed = 1) {
  const docs = []
  for (let i = 0; i < count; i++) {
    const r = rng(seed * 100003 + i * 7919)
    const pick = a => a[Math.floor(r() * a.length)]
    const word = () => pick(WORDS)
    const words = (n) => Array.from({length: n}, word).join(' ')
    const inline = () => {
      const parts = []
      const n = 3 + Math.floor(r() * 9)
      for (let k = 0; k < n; k++) {
        const w = word()
        parts.push(pick([w, w, w, `*${w}*`, `**${w}**`, `_${w}_`, `***${w}***`, `~~${w}~~`, `\`${w}\``, `[${w}](https://example.com/${w} "t")`, `[${w}][ref${k % 3}]`, `![${w}](img/${w}.png)`, `<https://example.com/${w}>`, `www.${w}.com`, `${w}@example.com`, `&amp; &copy; &#35;`, `\\*${w}\\*`, `<span class="x">${w}</span>`, `${w}[^${k % 2 + 1}]`, `${w}\\`, `${w}  `]))
      }
      return parts.join(' ')
    }
    const indent = () => pick(['', '', '  ', '   ', '\t'])
    const list = (depth = 0) => {
      const ordered = r() < 0.4
      const n = 2 + Math.floor(r() * 4)
      const pad = '  '.repeat(depth)
      let out = ''
      for (let k = 0; k < n; k++) {
        const marker = ordered ? `${k + 1}${pick(['.', ')'])}` : pick(['-', '*', '+'])
        const task = r() < 0.15 ? pick(['[ ] ', '[x] ']) : ''
        out += `${pad}${marker} ${task}${inline()}\n`
        if (r() < 0.2) out += `\n${pad}  ${inline()}\n`
        if (depth < 2 && r() < 0.3) out += list(depth + 1)
      }
      return out
    }
    const table = () => {
      const cols = 2 + Math.floor(r() * 3)
      const row = () => '| ' + Array.from({length: cols}, () => pick([word(), `\`${word()}\``, `*${word()}*`, 'a \\| b', ''])).join(' | ') + ' |\n'
      return row() + '| ' + Array.from({length: cols}, () => pick(['---', ':--', '--:', ':-:'])).join(' | ') + ' |\n' + row() + row()
    }
    const quote = () => '> ' + inline() + '\n' + (r() < 0.5 ? '> > ' + inline() + '\n' : '') + (r() < 0.4 ? 'lazy ' + inline() + '\n' : '')
    const fence = () => { const f = pick(['```', '~~~', '````']); return `${f}${pick(['', 'js', 'python title="x"', ' sh'])}\n${words(3)}\n${r() < 0.3 ? f.slice(0, 3) + ' not a close\n' : ''}${words(4)}\n${f}\n` }
    const html = () => pick(['<div>\n' + words(3) + '\n</div>\n', '<!-- ' + words(2) + ' -->\n', '<details>\n<summary>' + word() + '</summary>\n\n' + inline() + '\n\n</details>\n', '<pre>\n' + words(3) + '\n</pre>\n', '<br>\n'])
    const blocks = {
      heading: () => `${'#'.repeat(1 + Math.floor(r() * 6))} ${inline()}\n`,
      setext: () => `${words(3)}\n${pick(['===', '---', '------'])}\n`,
      para: () => inline() + '\n' + (r() < 0.5 ? inline() + '\n' : ''),
      list, table, quote, fence, html,
      indented: () => `${'    '}${words(3)}\n    ${words(2)}\n`,
      rule: () => pick(['---', '***', '___', '- - -']) + '\n',
      def: () => `[ref${Math.floor(r() * 3)}]: https://example.com/${word()}${pick(['', ' "title"', " 'title'", ' (title)'])}\n`,
      footnote: () => `[^${1 + Math.floor(r() * 2)}]: ${inline()}\n\n    ${inline()}\n`,
      chat: () => chatAnswer(400 + Math.floor(r() * 1200), 1 + Math.floor(r() * 1000)) + '\n'
    }
    const kinds = Object.keys(blocks)
    let doc = ''
    if (r() < 0.2) doc += `---\ntitle: ${words(2)}\ntags: [a, b]\n---\n\n`
    const n = 6 + Math.floor(r() * 24)
    for (let k = 0; k < n; k++) {
      const kind = pick(kinds)
      doc += (r() < 0.12 ? indent() : '') + blocks[kind]() + (r() < 0.9 ? '\n' : '')
    }
    const eol = r()
    if (eol < 0.08) doc = doc.replace(/\n/g, '\r\n')
    else if (eol < 0.12) doc = doc.replace(/\n/g, '\r')
    if (r() < 0.1) doc = doc.replace(/\n+$/, '')
    docs.push({id: `synthetic/${String(i).padStart(4, '0')}.md`, src: doc})
  }
  return docs
}
